# Runtime v2 · LO Layout: constraints, một lượt đo, Layout tùy chỉnh, intrinsic, SubcomposeLayout (chương mới)
# Nguồn: "Custom layouts", "Compose layout basics", "Intrinsic measurements in Compose layouts", "Constraints and modifier order" (developer.android.com, đọc 2026-11-23);
# MeasurePolicy.kt, Measurable.kt, LayoutNodeLayoutDelegate.kt (MeasuredTwiceErrorMessage), MeasurePassDelegate.kt, SubcomposeLayout.kt, Constraints.kt @296313a4;
# Kunneth Ch.4 ("Understanding the single measure pass", "Creating custom layouts": SimpleFlexBox); Essentials Ch.28 (exampleLayout), Ch.29 (CascadeLayout), Ch.32 (IntrinsicSize).

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.measure ----------------
    m = lambda k, vi, en=None: a('m.measure.' + k, vi, en)
    m('title', 'Một lượt layout: đo con, quyết kích thước, đặt con', 'One layout pass: measure children, decide the size, place children')
    m('overview', 'Một `Layout` cha nhận constraints 0..360 × 0..640 px từ cha của nó và có ba con. Chọn một trong bốn kịch bản: cột tự viết (`MyBasicColumn`), đo một con hai lần, `Row` có đường chia dọc `fillMaxHeight()` không dùng intrinsic, và cùng `Row` đó với `height(IntrinsicSize.Min)`. Theo dõi số lần đo, số lần hỏi intrinsic và chiều cao cha chọn.', 'A parent `Layout` receives constraints 0..360 × 0..640 px from its own parent and has three children. Pick one of four scenarios: a hand-written column (`MyBasicColumn`), measuring one child twice, a `Row` with a `fillMaxHeight()` vertical divider without intrinsics, and the same `Row` with `height(IntrinsicSize.Min)`. Watch the number of measurements, the number of intrinsic queries and the height the parent chooses.')
    m('wrapup', 'Mỗi node làm ba bước: đo con, quyết kích thước của mình, đặt con. Mỗi con chỉ được đo MỘT lần trong một lượt; đo lại sẽ ném `IllegalStateException`.\nKhi cha cần biết kích thước của con TRƯỚC khi chọn constraints để đo, nó hỏi intrinsic: một câu hỏi rẻ hơn, không phải lần đo thứ hai. Nhờ vậy cây sâu bao nhiêu thì layout vẫn tuyến tính theo số node.\nQuy tắc dễ nhớ: đo một lần thôi; cần biết trước thì "hỏi" chứ đừng "đo thử".',
      'Every node does three steps: measure its children, decide its own size, place its children. Each child may be measured only ONCE per pass; measuring again throws `IllegalStateException`.\nWhen the parent needs a child\'s size BEFORE choosing the constraints to measure it with, it asks for intrinsics: a cheaper question, not a second measurement. That keeps layout linear in the number of nodes, however deep the tree.\nRule of thumb: measure only once; if you need to know in advance, "ask" rather than "trial-measure".')
    m('simp.1', 'Số px (360, 640, 40, 48, 72, 179) là minh họa; kích thước thật phụ thuộc font, mật độ màn hình và padding. Mô hình bỏ qua modifier (padding, weight) như những node riêng, chỉ giữ ảnh hưởng của chúng lên con số.', 'The pixel numbers (360, 640, 40, 48, 72, 179) are illustrative; real sizes depend on fonts, screen density and padding. The model does not show modifiers (padding, weight) as separate nodes, only their effect on the numbers.')
    m('simp.2', 'Thứ tự trong `Row` thật khác một chút: con có `weight` được đo sau con không có `weight`. Mô hình đo theo thứ tự xuất hiện để giữ ý chính: mỗi con một lần.', 'The order inside a real `Row` differs slightly: children with `weight` are measured after those without. The model measures in order of appearance to keep the main point: each child once.')
    m('ctl.hint', 'Chạy cột trước, rồi thử đo hai lần; sau đó so hai kịch bản Row.', 'Run the column first, then try measuring twice; then compare the two Row scenarios.')
    m('ctl.which', 'Kịch bản', 'Scenario')
    for k, vi, en in [('col', 'MyBasicColumn: ba Text', 'MyBasicColumn: three Texts'), ('twice', 'Đo một con hai lần (✗)', 'Measure one child twice (✗)'),
                      ('nointr', 'Row + VerticalDivider, không intrinsic', 'Row + VerticalDivider, no intrinsics'), ('intr', 'Row.height(IntrinsicSize.Min)', 'Row.height(IntrinsicSize.Min)')]:
        m('ctl.which.' + k, vi, en)
    m('diagramTitle', 'Một Layout cha và ba con', 'A parent Layout and three children')
    m('diagramDesc', 'Layout cha ở trên nối xuống ba con; tín hiệu đi xuống là lời gọi measure hoặc câu hỏi intrinsic, tín hiệu đặt con đi xuống sau khi cha đã có kích thước', 'The parent Layout at the top connects down to three children; signals going down are measure calls or intrinsic queries, and placement signals go down after the parent has its size')
    for k, vi, en in [('parent', 'Layout cha', 'Parent Layout'), ('k1', 'Con 1', 'Child 1'), ('k2', 'Con 2', 'Child 2'), ('k3', 'Con 3', 'Child 3')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('measured', 'Lần gọi measure()', 'measure() calls'), ('queries', 'Lần hỏi intrinsic', 'Intrinsic queries'), ('height', 'Chiều cao cha (px)', 'Parent height (px)')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('cons', 'Constraints cho con (rộng × cao)', 'Constraints for children (width × height)'), ('last', 'Kết quả gần nhất', 'Latest result'), ('pos', 'Vị trí đặt', 'Placement')]:
        m('st.' + k, vi, en)
    S = [
        ('col.intro', 'Cha nhận constraints', 'The parent receives constraints', 'Khối đo của `MyBasicColumn` nhận `measurables` (ba `Text`) và `constraints` 0..360 × 0..640 px. Nó không thu hẹp constraints mà đo mỗi con với đúng constraints được nhận.', 'The measure block of `MyBasicColumn` receives `measurables` (three `Text`s) and `constraints` 0..360 × 0..640 px. It does not narrow the constraints; it measures each child with exactly the constraints it got.'),
        ('col.m1', 'Đo con 1', 'Measure child 1', '`measure(constraints)` trả về một `Placeable`: kích thước con đã chọn, ở đây 360×40. Cha không được "mặc cả": con đã chọn thì cha phải xử lý kích thước đó.', '`measure(constraints)` returns a `Placeable`: the size the child chose, here 360×40. The parent cannot "negotiate": once the child has chosen, the parent must deal with that size.'),
        ('col.m2', 'Đo con 2', 'Measure child 2', 'Con 2 cũng chọn 360×40. Mỗi con được đo đúng một lần.', 'Child 2 also chooses 360×40. Each child is measured exactly once.'),
        ('col.m3', 'Đo con 3', 'Measure child 3', 'Con 3 xuống hai dòng nên cao 60.', 'Child 3 wraps onto two lines, so it is 60 tall.'),
        ('col.size', 'Cha quyết kích thước của mình', 'The parent decides its own size', '`layout(constraints.maxWidth, constraints.maxHeight)`: cột này chiếm hết chỗ được cho, 360×640, bất kể con cao bao nhiêu. Đây là lựa chọn của ví dụ, không phải luật.', '`layout(constraints.maxWidth, constraints.maxHeight)`: this column takes all the space it is given, 360×640, regardless of the children\'s heights. This is the example\'s choice, not a rule.'),
        ('col.place', 'Đặt con theo y tích lũy', 'Place children by accumulated y', 'Trong khối đặt, `placeRelative(x = 0, y = yPosition)` rồi cộng chiều cao: y = 0, 40, 80. Con không được đặt thì không hiện ra.', 'In the placement block, `placeRelative(x = 0, y = yPosition)`, then add the height: y = 0, 40, 80. A child that is not placed is not shown.'),
        ('col.end', 'Kết thúc: 3 lần đo cho 3 con', 'The end: 3 measurements for 3 children', 'Cha đo trước con, nhưng có kích thước và đặt con sau khi các con đã có kích thước.', 'The parent measures before its children, but gets its size and places them after the children have theirs.'),
        ('tw.intro', 'Một layout muốn "đo thử"', 'A layout that wants a "trial" measurement', 'Ý định: đo con một lần để biết nó rộng bao nhiêu, rồi đo lại với nửa chiều rộng đó. Trong hệ View, cha có thể gọi `measure()` nhiều lần cho cùng một con.', 'The intent: measure the child once to learn its width, then measure again with half that width. In the View system a parent may call `measure()` several times on the same child.'),
        ('tw.m1', 'Lần đo thứ nhất', 'The first measurement', 'Lần đo hợp lệ: con chọn 360×40.', 'A valid measurement: the child chooses 360×40.'),
        ('tw.again', 'Lần đo thứ hai: exception', 'The second measurement: an exception', 'Node con ghi nhận nó đã được cha đo trong lượt này. Lần gọi thứ hai trên cùng `Measurable` không qua được kiểm tra và ném `IllegalStateException`.', 'The child node records that its parent has already measured it in this pass. The second call on the same `Measurable` fails the check and throws `IllegalStateException`.'),
        ('tw.end', 'Kết thúc: lượt layout dừng', 'The end: the layout pass stops', 'Thông điệp lỗi tự chỉ hướng sửa: muốn biết kích thước nội dung trước khi chọn constraints cuối thì dùng `minIntrinsicWidth()`/`maxIntrinsicWidth()` và `minIntrinsicHeight()`/`maxIntrinsicHeight()`.', 'The error message itself points to the fix: to learn the content size before choosing the final constraints, use `minIntrinsicWidth()`/`maxIntrinsicWidth()` and `minIntrinsicHeight()`/`maxIntrinsicHeight()`.'),
        ('no.intro', 'Row với hai Text và một đường chia', 'A Row with two Texts and a divider', 'Mục tiêu: đường chia dọc cao bằng Text cao nhất. Đường chia dùng `fillMaxHeight()`. `Row` không có chiều cao cố định, nên con nhận chiều cao tối đa 640.', 'The goal: a vertical divider as tall as the tallest Text. The divider uses `fillMaxHeight()`. The `Row` has no fixed height, so its children get a maximum height of 640.'),
        ('no.m1', 'Đo Text 1', 'Measure Text 1', 'Text 1 (weight 1f) chọn 179×48.', 'Text 1 (weight 1f) chooses 179×48.'),
        ('no.m2', 'Đo đường chia: cao 640', 'Measure the divider: 640 tall', '`fillMaxHeight()` lấy chiều cao TỐI ĐA được cho: 640. `Row` đo từng con riêng, nên chiều cao của Text không thể giới hạn đường chia.', '`fillMaxHeight()` takes the MAXIMUM height it is given: 640. The `Row` measures each child separately, so a Text\'s height cannot constrain the divider.'),
        ('no.m3', 'Đo Text 2', 'Measure Text 2', 'Text 2 xuống ba dòng: 179×72.', 'Text 2 wraps onto three lines: 179×72.'),
        ('no.size', 'Row cao bằng con cao nhất: 640', 'The Row is as tall as its tallest child: 640', '`Row` chọn chiều cao bằng con cao nhất, và con cao nhất giờ là đường chia.', 'The `Row` picks the height of its tallest child, and the tallest child is now the divider.'),
        ('no.place', 'Đặt ba con theo x', 'Place the three children by x', 'Ba con nằm cạnh nhau ở x = 0, 179, 180.', 'The three children sit side by side at x = 0, 179, 180.'),
        ('no.end', 'Kết thúc: đường chia kéo dài hết màn hình', 'The end: the divider stretches across the whole screen', 'Đúng hình mà trang Intrinsic measurements mô tả: đường chia giãn theo chiều cao tối đa, không theo Text.', 'Exactly what the Intrinsic measurements page describes: the divider stretches to the maximum height, not to the Text.'),
        ('in.intro', 'Cùng Row, thêm height(IntrinsicSize.Min)', 'The same Row, plus height(IntrinsicSize.Min)', 'Modifier này hỏi `minIntrinsicHeight` của Row TRƯỚC khi đo. `minIntrinsicHeight` của Row là giá trị lớn nhất của các con.', 'This modifier asks for the Row\'s `minIntrinsicHeight` BEFORE measuring. The Row\'s `minIntrinsicHeight` is the largest of its children\'s.'),
        ('in.q1', 'Hỏi Text 1: minIntrinsicHeight', 'Ask Text 1: minIntrinsicHeight', 'Với chiều rộng được chia, Text 1 cần ít nhất 48 để vẽ đủ nội dung. Đây là câu hỏi, không phải lần đo: chưa có `Placeable` nào.', 'At its share of the width, Text 1 needs at least 48 to draw all its content. This is a query, not a measurement: no `Placeable` exists yet.'),
        ('in.q2', 'Hỏi đường chia: 0', 'Ask the divider: 0', 'Đường chia không chiếm chỗ khi không có constraints, nên `minIntrinsicHeight` của nó là 0.', 'The divider takes no space without constraints, so its `minIntrinsicHeight` is 0.'),
        ('in.q3', 'Hỏi Text 2: 72', 'Ask Text 2: 72', 'Text 2 cần 72. Giá trị lớn nhất là 72.', 'Text 2 needs 72. The largest value is 72.'),
        ('in.fixed', 'Chiều cao cố định 72', 'A fixed height of 72', '`height(IntrinsicSize.Min)` biến 72 thành constraints chính xác cho Row: con giờ nhận chiều cao tối đa 72 thay vì 640.', '`height(IntrinsicSize.Min)` turns 72 into exact constraints for the Row: the children now get a maximum height of 72 instead of 640.'),
        ('in.m1', 'Đo Text 1 (lần duy nhất)', 'Measure Text 1 (the only time)', 'Text 1 chọn 179×48.', 'Text 1 chooses 179×48.'),
        ('in.m2', 'Đo đường chia: cao 72', 'Measure the divider: 72 tall', '`fillMaxHeight()` giờ lấy tối đa 72.', '`fillMaxHeight()` now takes a maximum of 72.'),
        ('in.m3', 'Đo Text 2', 'Measure Text 2', 'Text 2 chọn 179×72.', 'Text 2 chooses 179×72.'),
        ('in.size', 'Row cao 72', 'The Row is 72 tall', 'Chiều cao Row là 72, theo constraints chính xác.', 'The Row height is 72, following the exact constraints.'),
        ('in.place', 'Đặt ba con theo x', 'Place the three children by x', 'Ba con nằm cạnh nhau ở x = 0, 179, 180.', 'The three children sit side by side at x = 0, 179, 180.'),
        ('in.end', 'Kết thúc: 3 câu hỏi, 3 lần đo', 'The end: 3 queries, 3 measurements', 'Đường chia cao bằng Text cao nhất. Mỗi con vẫn chỉ được đo một lần.', 'The divider is as tall as the tallest Text. Each child is still measured only once.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('single', 'Mỗi node: đo con, quyết kích thước, đặt con. Cha đo trước con nhưng có kích thước và được đặt sau con. [[src:cp-layout-custom]] [[src:cp-layout-basics]]', 'Each node: measure children, decide its size, place children. Parents measure before their children but are sized and placed after them. [[src:cp-layout-custom]] [[src:cp-layout-basics]]'),
        ('twice', 'Ở commit ghim, `trackMeasurementByParent` kiểm tra node chưa được cha dùng trong lượt này; không thì ném lỗi với thông điệp `MeasuredTwiceErrorMessage`. [[src:ui-measure-once]]', 'At the pinned commit, `trackMeasurementByParent` checks that the node has not yet been used by its parent in this pass; otherwise it throws with the `MeasuredTwiceErrorMessage` message. [[src:ui-measure-once]]'),
        ('noTwice', 'Tài liệu: hỏi intrinsic không đo con hai lần. Con được hỏi trước khi đo, rồi cha dựa vào đó để tính constraints đo con. [[src:cp-intrinsics]]', 'The docs: asking for intrinsics does not measure children twice. Children are queried before they are measured, then the parent uses that to compute the constraints to measure them with. [[src:cp-intrinsics]]'),
        ('nointr', '`Row` đo từng con riêng, nên chiều cao Text không giới hạn được đường chia `fillMaxHeight()`. [[src:cp-intrinsics]]', 'A `Row` measures each child separately, so a Text\'s height cannot constrain the `fillMaxHeight()` divider. [[src:cp-intrinsics]]'),
        ('intr', '`minIntrinsicHeight` của Row là max của các con; của đường chia là 0; của Text là chiều cao ở chiều rộng cho trước. [[src:cp-intrinsics]]', 'The Row\'s `minIntrinsicHeight` is the max of its children\'s; the divider\'s is 0; a Text\'s is its height at the given width. [[src:cp-intrinsics]]')]:
        m('co.' + k, vi, en)
    a('cap.measure', 'Layout cha ở trên, ba con ở dưới. Tín hiệu cha → con là một lần đo hoặc một câu hỏi intrinsic; lượt cuối cha → con là lúc đặt con. Chỉ số trên cùng đếm số lần đo, số lần hỏi và chiều cao cha chọn.', 'The parent Layout is at the top and the three children below it. A parent → child signal is a measurement or an intrinsic query; the last round of parent → child signals is placement. The metrics at the top count measurements, queries and the height the parent chose.')

    # ---------------- chương LO (mới) ----------------
    C = 'lo'
    a(C + '.title', 'Layout: constraints, một lượt đo, Layout tùy chỉnh và intrinsic', 'Layout: constraints, single-pass measurement, custom layouts and intrinsics')
    a(C + '.essence',
      'Phase layout (chương B7) chạy trên cây `LayoutNode`. Mỗi node làm ba bước: đo các con, quyết kích thước của mình, đặt các con. Cha truyền xuống constraints: khoảng min..max cho chiều rộng và chiều cao. Con chọn kích thước trong khoảng đó và trả về một `Placeable`; cha đặt nó bằng `place`/`placeRelative`.\n'
      'Luật quan trọng nhất: mỗi con chỉ được đo MỘT lần trong một lượt. Đo lại ném exception. Nhờ vậy layout tuyến tính theo số node, và lồng sâu không tốn thêm như hệ View. Khi cha thật sự cần biết con lớn bao nhiêu trước khi đo, nó hỏi intrinsic (`IntrinsicSize.Min`/`Max`).\n'
      'Chương đi từ mô hình, qua constraints, tới tự viết layout bằng `Modifier.layout` và `Layout`, rồi intrinsic và `SubcomposeLayout`, cửa sau cho phép compose trong lúc đo.',
      'The layout phase (chapter B7) runs over the tree of `LayoutNode`s. Every node does three steps: measure its children, decide its own size, place its children. The parent passes down constraints: a min..max range for width and height. The child chooses a size within that range and returns a `Placeable`; the parent places it with `place`/`placeRelative`.\n'
      'The most important rule: each child may be measured only ONCE per pass. Measuring again throws an exception. This keeps layout linear in the number of nodes, and deep nesting costs nothing extra, unlike the View system. When a parent really needs to know how big a child is before measuring it, it asks for intrinsics (`IntrinsicSize.Min`/`Max`).\n'
      'The chapter goes from the model, through constraints, to writing layouts yourself with `Modifier.layout` and `Layout`, then intrinsics and `SubcomposeLayout`, the back door that allows composing during measurement.')
    a(C + '.goal.g1', 'Đã thấy cha hỏi con đầu tiên (đo, hoặc hỏi intrinsic)', 'Saw the parent ask its first child (a measurement or an intrinsic query)')
    a(C + '.goal.g2', 'Đã chạy một kịch bản tới cuối', 'Ran one scenario to the end')
    a(C + '.sim.runtime.measure', 'Một lượt layout', 'One layout pass')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Một `Row` chứa `Text`, một `VerticalDivider(Modifier.fillMaxHeight().width(1.dp))` rồi `Text`. Row nằm trên cùng một màn hình trống, không đặt chiều cao. Đường chia cao bao nhiêu?', 'A `Row` holds a `Text`, a `VerticalDivider(Modifier.fillMaxHeight().width(1.dp))`, then a `Text`. The Row sits at the top of an empty screen with no height set. How tall is the divider?')
    B(C, S, 1, 'ans', 'Cao gần hết màn hình, không phải bằng Text. `fillMaxHeight()` lấy chiều cao tối đa mà constraints cho, và Row đo từng con riêng nên chiều cao Text không giới hạn được đường chia. Cách sửa (`height(IntrinsicSize.Min)`) nằm ở mục intrinsic và trong mô phỏng. [[src:cp-intrinsics]]', 'Nearly the whole screen, not the Text\'s height. `fillMaxHeight()` takes the maximum height its constraints allow, and the Row measures each child separately, so the Text\'s height cannot constrain the divider. The fix (`height(IntrinsicSize.Min)`) is in the intrinsics section and the simulation. [[src:cp-intrinsics]]')

    S = 'model'
    a(C + '.sec.%s.title' % S, 'Mô hình layout: một lượt, ba bước', 'The layout model: one pass, three steps')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Mỗi phần tử giao diện có một cha, có thể có nhiều con. Nó nằm ở một vị trí (x, y) trong cha, và có chiều rộng, chiều cao.\nCha đặt ra constraints (giới hạn kích thước) cho con; con chọn kích thước nằm trong đó. Mỗi node đi qua ba bước: (1) đo các con; (2) quyết kích thước của mình; (3) đặt các con theo vị trí so với mình [[src:cp-layout-custom]].\nQuy tắc dễ nhớ: cha ra luật, con chọn cỡ trong luật, cha xếp chỗ.',
      'Every interface element has one parent and possibly many children. It sits at an (x, y) position inside its parent, and has a width and a height.\nThe parent sets constraints (size limits) for its children; a child chooses a size within them. Every node goes through three steps: (1) measure its children; (2) decide its own size; (3) place its children relative to itself [[src:cp-layout-custom]].\nRule of thumb: the parent sets the rules, the child picks a size within them, the parent arranges the seats.')
    B(C, S, 2, 'p', 'Trang Layout basics tóm lại: cây giao diện được layout trong MỘT lượt. Mỗi node được yêu cầu tự đo, rồi đo con một cách đệ quy, truyền constraints xuống dưới. Lá có kích thước trước; kích thước và chỉ dẫn đặt chỗ được trả ngược lên trên.\nNói gọn: cha đo trước con, nhưng có kích thước và được đặt chỗ sau con. Với `Row(Image, Column(Text, Text))`: Row hỏi Image (là lá, nó báo kích thước); Row hỏi Column; Column lần lượt hỏi hai Text, quyết kích thước của mình và đặt hai Text; rồi Row cũng làm như vậy [[src:cp-layout-basics]].',
      'The Layout basics page sums it up: the interface tree is laid out in ONE pass. Each node is asked to measure itself, then measures its children recursively, passing constraints down. Leaves get their size first; sizes and placement instructions flow back up.\nIn short: a parent measures before its children, but gets its size and its place after them. With `Row(Image, Column(Text, Text))`: the Row asks the Image (a leaf, which reports its size); the Row asks the Column; the Column asks each Text in turn, decides its own size and places the two Texts; then the Row does the same [[src:cp-layout-basics]].')
    B(C, S, 3, 'p', 'Vì sao "một lượt" lại quan trọng? Trong hệ View, một ViewGroup có thể gọi `measure()` nhiều lần trên con để thử nhiều cấu hình, và việc đo lại làm giảm hiệu năng. Nếu mỗi tầng đo con hai lần, cây sâu 10 tầng có thể đo một lá tới 2^10 lần.\nCompose cấm chuyện đó. Vì vậy tài liệu nói bạn có thể lồng sâu tuỳ ý mà không ảnh hưởng hiệu năng, khác hẳn lời khuyên tránh lồng `RelativeLayout` trong hệ View [[src:book-kunneth]] [[src:cp-layout-basics]].\nQuy tắc dễ nhớ: trong Compose, lồng sâu không đáng sợ; đo nhiều lần mới đáng sợ, và Compose đã cấm nó.',
      'Why does "one pass" matter? In the View system, a ViewGroup may call `measure()` several times on a child to try different configurations, and measuring again hurts performance. If every level measured its children twice, a tree 10 levels deep could measure one leaf up to 2^10 times.\nCompose forbids that. So the docs say you can nest as deeply as you like without hurting performance, quite unlike the advice to avoid nesting `RelativeLayout` in the View system [[src:book-kunneth]] [[src:cp-layout-basics]].\nRule of thumb: in Compose, deep nesting is not scary; measuring many times is, and Compose has forbidden it.')
    B(C, S, 4, 'note', 'Đo và đặt là hai bước con tách riêng của phase layout. Như B7, một thay đổi chỉ ảnh hưởng tới vị trí (state đọc trong `Modifier.offset { }`) có thể chạy lại riêng bước đặt, không cần đo lại [[src:cp-layout-basics]] [[src:cp-phases]].',
      'Measuring and placing are separate sub-steps of the layout phase. As in B7, a change that only affects position (state read inside `Modifier.offset { }`) can re-run the placing step alone, without measuring again [[src:cp-layout-basics]] [[src:cp-phases]].')
    B(C, S, 4, 'kind', 'mechanism')

    S = 'constraints'
    a(C + '.sec.%s.title' % S, 'Constraints: khoảng cho phép', 'Constraints: the allowed range')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`Constraints` (gói `androidx.compose.ui.unit`) giữ bốn số, tính bằng px: `minWidth`, `maxWidth`, `minHeight`, `maxHeight`. Con phải chọn chiều rộng trong [minWidth, maxWidth] và chiều cao trong [minHeight, maxHeight].\n`Constraints.Infinity` (bằng `Int.MAX_VALUE` ở commit ghim) nghĩa là không giới hạn; khi max là Infinity thì `hasBoundedWidth`/`hasBoundedHeight` là false. Có sẵn `Constraints.fixed(w, h)`, `fixedWidth`, `fixedHeight`. Lưu ý: đây không phải "constraint" của `ConstraintLayout` [[src:ui-constraints-src]] [[src:book-kunneth]].\nQuy tắc dễ nhớ: constraints là bốn con số "rộng từ… đến…, cao từ… đến…".',
      '`Constraints` (package `androidx.compose.ui.unit`) holds four numbers, in px: `minWidth`, `maxWidth`, `minHeight`, `maxHeight`. A child must choose a width in [minWidth, maxWidth] and a height in [minHeight, maxHeight].\n`Constraints.Infinity` (`Int.MAX_VALUE` at the pinned commit) means unbounded; when the max is Infinity, `hasBoundedWidth`/`hasBoundedHeight` are false. There are ready-made `Constraints.fixed(w, h)`, `fixedWidth` and `fixedHeight`. Note: these are not the "constraints" of `ConstraintLayout` [[src:ui-constraints-src]] [[src:book-kunneth]].\nRule of thumb: constraints are four numbers: "width from… to…, height from… to…".')
    B(C, S, 2, 'p', 'Trang Constraints and modifier order chia bốn loại:\n• Bounded: có min và max.\n• Unbounded: max là vô cực, ví dụ bên trong một vùng cuộn theo chiều đó.\n• Exact: min bằng max, kích thước bị ép đúng một giá trị.\n• Kết hợp: ví dụ rộng exact, cao bounded.\nVì sao con phụ thuộc constraints? Một `Text` dài sẽ cao hơn khi điện thoại dựng dọc (hẹp) so với khi nằm ngang, vì chiều rộng tối đa của cha quyết định số dòng [[src:cp-constraints-mod]] [[src:book-kunneth]].',
      "The Constraints and modifier order page names four kinds:\n• Bounded: a min and a max.\n• Unbounded: the max is infinity, for example inside a scrolling area in that direction.\n• Exact: min equals max, the size is forced to one value.\n• Combined: for example an exact width with a bounded height.\nWhy does a child depend on its constraints? A long `Text` is taller when the phone is upright (narrow) than when it is sideways, because the parent's maximum width decides the number of lines [[src:cp-constraints-mod]] [[src:book-kunneth]].")
    B(C, S, 3, 'predict', 'Trong một khung 300×200 dp, `Image(…, Modifier.fillMaxSize().size(50.dp))` to bao nhiêu?', 'Inside a 300×200 dp container, how big is `Image(…, Modifier.fillMaxSize().size(50.dp))`?')
    B(C, S, 3, 'ans', '300×200, không phải 50. `fillMaxSize` đặt min = max = 300×200 (exact); `size` phải tôn trọng constraints vào, nên nó chọn giá trị gần 50 nhất trong khoảng cho phép, tức 300×200. Muốn 50 dp ở giữa thì chèn `wrapContentSize()` giữa hai modifier: nó nới min về 0 rồi căn giữa con. Thứ tự modifier là chủ đề của chương MD. [[src:cp-constraints-mod]]', '300×200, not 50. `fillMaxSize` sets min = max = 300×200 (exact); `size` must respect the incoming constraints, so it picks the value closest to 50 within the allowed range, which is 300×200. For a centred 50 dp, put `wrapContentSize()` between the two modifiers: it relaxes the minimums to 0 and centres the child. Modifier order is the subject of chapter MD. [[src:cp-constraints-mod]]')
    B(C, S, 4, 'p', 'KDoc của `MeasurePolicy` ở commit ghim nói rõ: không có thương lượng kích thước giữa cha và con. Con đã chọn thì cha phải xoay xở được.\nCon được phép chọn kích thước nằm ngoài constraints. Khi đó `Placeable.width`/`height` là kích thước đã bị ép về khoảng constraints, và vị trí được tự dịch để con nằm giữa phần chỗ cha dành cho nó. Kích thước thật đọc ở `measuredWidth`/`measuredHeight`. Đó là cách `requiredSize` "tràn" ra ngoài mà vẫn được căn giữa [[src:ui-measurepolicy-src]] [[src:cp-constraints-mod]].',
      'The `MeasurePolicy` KDoc at the pinned commit is clear: there is no size negotiation between parent and child. Once the child chooses, the parent must cope.\nA child may choose a size outside its constraints. Then `Placeable.width`/`height` are the size squeezed into the constraints, and the position is shifted automatically so the child is centred in the space the parent gave it. The true size is in `measuredWidth`/`measuredHeight`. That is how `requiredSize` "overflows" and still ends up centred [[src:ui-measurepolicy-src]] [[src:cp-constraints-mod]].')

    S = 'modifier'
    a(C + '.sec.%s.title' % S, 'Modifier.layout: đo và đặt MỘT phần tử', 'Modifier.layout: measuring and placing ONE element')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Cách nhỏ nhất để can thiệp vào layout là `Modifier.layout { measurable, constraints -> … }`. Lambda nhận phần tử được bọc (`measurable`) và constraints đi vào.\nBên trong, làm ba việc: đo phần tử; gọi `layout(width, height)` để báo kích thước của lớp bọc; rồi trong khối của `layout`, đặt phần tử bằng `placeRelative`. Ví dụ của tài liệu: khoảng cách từ mép trên tới baseline đầu tiên của một Text, đúng việc `paddingFromBaseline` làm sẵn [[src:cp-layout-custom]].\nQuy tắc dễ nhớ: cần đổi cách đo hay đặt của MỘT phần tử thì dùng `Modifier.layout`.',
      "The smallest way to step into layout is `Modifier.layout { measurable, constraints -> … }`. The lambda receives the wrapped element (`measurable`) and the incoming constraints.\nInside, do three things: measure the element; call `layout(width, height)` to report the wrapper's size; then, inside the `layout` block, place the element with `placeRelative`. The docs' example: the distance from the top edge to a Text's first baseline, exactly what `paddingFromBaseline` already does [[src:cp-layout-custom]].\nRule of thumb: to change how ONE element is measured or placed, use `Modifier.layout`.")
    B(C, S, 2, 'kt', 'fun Modifier.firstBaselineToTop(firstBaselineToTop: Dp) = layout { measurable, constraints ->\n    val placeable = measurable.measure(constraints)              // đo phần tử được bọc\n    check(placeable[FirstBaseline] != AlignmentLine.Unspecified)\n    val firstBaseline = placeable[FirstBaseline]\n    val placeableY = firstBaselineToTop.roundToPx() - firstBaseline\n    val height = placeable.height + placeableY\n    layout(placeable.width, height) {                             // kích thước của lớp bọc\n        placeable.placeRelative(0, placeableY)                    // không đặt thì không hiện\n    }\n}', 'fun Modifier.firstBaselineToTop(firstBaselineToTop: Dp) = layout { measurable, constraints ->\n    val placeable = measurable.measure(constraints)              // measure the wrapped element\n    check(placeable[FirstBaseline] != AlignmentLine.Unspecified)\n    val firstBaseline = placeable[FirstBaseline]\n    val placeableY = firstBaselineToTop.roundToPx() - firstBaseline\n    val height = placeable.height + placeableY\n    layout(placeable.width, height) {                             // the wrapper\'s size\n        placeable.placeRelative(0, placeableY)                    // not placed = not shown\n    }\n}')
    B(C, S, 3, 'p', 'Một ví dụ đơn giản hơn: `Modifier.exampleLayout(x, y)` đo con với constraints nhận được, báo kích thước bằng đúng kích thước con, rồi gọi `placeRelative(x, y)`.\nĐiểm cần nhớ: toạ độ ở đây là độ lệch so với vị trí MẶC ĐỊNH mà cha đã chọn. Nếu cha đặt con ở (50, 70) và modifier trả về (20, 10), con sẽ nằm ở (70, 80). Modifier không cần biết cha là Box hay Row [[src:book-compose-ess]].',
      "A simpler example: `Modifier.exampleLayout(x, y)` measures the child with the constraints it got, reports exactly the child's size, then calls `placeRelative(x, y)`.\nThe point to remember: these coordinates are an offset from the DEFAULT position the parent chose. If the parent puts the child at (50, 70) and the modifier returns (20, 10), the child ends up at (70, 80). The modifier does not need to know whether the parent is a Box or a Row [[src:book-compose-ess]].")
    B(C, S, 4, 'p', '`placeRelative` lật trục x khi bố cục đi từ phải sang trái (RTL); `place` thì không. Hướng bố cục đọc ở `layoutDirection` của `MeasureScope`, và đổi được cho một nhánh bằng CompositionLocal `LocalLayoutDirection` (CL "CompositionLocal và slot API") [[src:cp-layout-custom]].\nQuy tắc dễ nhớ: mặc định dùng `placeRelative`, để giao diện tự đúng với ngôn ngữ viết từ phải sang trái.',
      '`placeRelative` mirrors the x axis when the layout runs right to left (RTL); `place` does not. The layout direction is available as `layoutDirection` on `MeasureScope`, and can be changed for a branch with the `LocalLayoutDirection` CompositionLocal (CL "CompositionLocal and slot APIs") [[src:cp-layout-custom]].\nRule of thumb: use `placeRelative` by default, so the interface is automatically right for right-to-left languages.')

    S = 'custom'
    a(C + '.sec.%s.title' % S, 'Layout: đo và đặt nhiều con', 'Layout: measuring and placing many children')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`Modifier.layout` chỉ đổi được phần tử gọi nó. Muốn đo và đặt nhiều con, dùng composable `Layout(modifier, content) { measurables, constraints -> … }`.\nĐây cũng chính là cách `Row`, `Column`, `Box` được viết: mở mã nguồn của `Column` sẽ thấy nó chỉ tính một `MeasurePolicy` rồi gọi `Layout`. Hệ View cần kế thừa `ViewGroup` và override `onMeasure`/`onLayout`; Compose chỉ cần một hàm [[src:cp-layout-custom]] [[src:book-kunneth]].\nQuy tắc dễ nhớ: một phần tử thì `Modifier.layout`; nhiều con thì `Layout`.',
      '`Modifier.layout` can only change the element that calls it. To measure and place many children, use the `Layout(modifier, content) { measurables, constraints -> … }` composable.\nThis is exactly how `Row`, `Column` and `Box` are written: open the source of `Column` and you find it only computes a `MeasurePolicy` and calls `Layout`. The View system needs a `ViewGroup` subclass overriding `onMeasure`/`onLayout`; Compose needs one function [[src:cp-layout-custom]] [[src:book-kunneth]].\nRule of thumb: one element uses `Modifier.layout`; many children use `Layout`.')
    B(C, S, 2, 'p', 'Lambda cuối chính là `MeasurePolicy.measure`, một hàm mở rộng của `MeasureScope`. Nó nhận một `List<Measurable>` (mỗi phần tử là một con layout) và trả về một `MeasureResult`, thường tạo bằng `layout(width, height) { … }`. `MeasureResult` gồm kích thước, các alignment line (như baseline của chữ) và khối đặt các con.\nQuy ước chung: layout tuỳ chỉnh nhận ít nhất `modifier: Modifier = Modifier` và `content: @Composable () -> Unit` (một slot API, CL). Mô phỏng ngay dưới chạy đúng `MyBasicColumn` của tài liệu [[src:ui-measurepolicy-src]] [[src:book-kunneth]] [[src:cp-layout-custom]].',
      "The trailing lambda is `MeasurePolicy.measure`, an extension function on `MeasureScope`. It receives a `List<Measurable>` (one per layout child) and returns a `MeasureResult`, usually built with `layout(width, height) { … }`. A `MeasureResult` holds the size, the alignment lines (such as text baselines) and the block that places the children.\nThe common convention: a custom layout takes at least `modifier: Modifier = Modifier` and `content: @Composable () -> Unit` (a slot API, CL). The simulation just below runs the docs' `MyBasicColumn` exactly [[src:ui-measurepolicy-src]] [[src:book-kunneth]] [[src:cp-layout-custom]].")
    B(C, S, 3, 'kt', '// SimpleFlexBox: xếp con từ trái sang phải, hết hàng thì xuống hàng\nprivate fun simpleFlexboxMeasurePolicy(): MeasurePolicy =\n    MeasurePolicy { measurables, constraints ->\n        val placeables = measurables.map { it.measure(constraints) }   // mỗi con một lần\n        layout(constraints.maxWidth, constraints.maxHeight) {\n            var xPos = 0; var yPos = 0; var maxY = 0\n            placeables.forEach { placeable ->\n                if (xPos + placeable.width > constraints.maxWidth) {     // không vừa: xuống hàng\n                    xPos = 0; yPos += maxY; maxY = 0\n                }\n                placeable.placeRelative(x = xPos, y = yPos)\n                xPos += placeable.width\n                if (maxY < placeable.height) maxY = placeable.height\n            }\n        }\n    }', '// SimpleFlexBox: children left to right, wrapping to a new row when full\nprivate fun simpleFlexboxMeasurePolicy(): MeasurePolicy =\n    MeasurePolicy { measurables, constraints ->\n        val placeables = measurables.map { it.measure(constraints) }   // each child once\n        layout(constraints.maxWidth, constraints.maxHeight) {\n            var xPos = 0; var yPos = 0; var maxY = 0\n            placeables.forEach { placeable ->\n                if (xPos + placeable.width > constraints.maxWidth) {     // does not fit: new row\n                    xPos = 0; yPos += maxY; maxY = 0\n                }\n                placeable.placeRelative(x = xPos, y = yPos)\n                xPos += placeable.width\n                if (maxY < placeable.height) maxY = placeable.height\n            }\n        }\n    }')
    B(C, S, 4, 'ask', 'Trong `SimpleFlexBox`, hàng mới bắt đầu cách hàng trước bao xa theo chiều dọc?', 'In `SimpleFlexBox`, how far below the previous row does a new row start?')
    B(C, S, 4, 'ans', 'Bằng chiều cao của con CAO NHẤT trong hàng trước (`maxY`), không phải chiều cao con cuối cùng.', 'By the height of the TALLEST child in the previous row (`maxY`), not the height of the last child.')
    B(C, S, 5, 'p', 'Đo một `Measurable` lần thứ hai trong cùng một lượt sẽ ném `IllegalStateException`.\nỞ commit ghim, mỗi node ghi lại cha đã dùng nó trong khối đo hay khối đặt (`measuredByParent`). Lần đo thứ hai thất bại với thông điệp "measure() may not be called multiple times on the same Measurable", kèm gợi ý dùng các hàm intrinsic. KDoc của `Measurable` nói thêm: đừng giữ instance này lại sau lượt layout [[src:ui-measure-once]] [[src:ui-measurepolicy-src]].',
      'Measuring a `Measurable` a second time in the same pass throws `IllegalStateException`.\nAt the pinned commit, each node records whether its parent used it in the measure block or the placement block (`measuredByParent`). A second measurement fails with the message "measure() may not be called multiple times on the same Measurable", plus a hint to use the intrinsic functions. The `Measurable` KDoc adds: never keep this instance beyond the layout pass [[src:ui-measure-once]] [[src:ui-measurepolicy-src]].')
    B(C, S, 5, 'kind', 'source')
    B(C, S, 6, 'p', 'Một chi tiết của mã ghim: con được phép đo bên trong khối đặt (`layout { … }`), không chỉ trong khối đo. Ví dụ một `CascadeLayout` đo các con ngay trong khối `layout`. Đo ở đâu thì luật vẫn là một lần.\nĐo trong khối đặt nghĩa là kích thước của con không thể ảnh hưởng tới kích thước của cha, vì cha đã báo kích thước xong rồi [[src:ui-measure-once]] [[src:book-compose-ess]].',
      "A detail of the pinned code: a child may be measured inside the placement block (`layout { … }`), not only in the measure block. For example, a `CascadeLayout` measures its children right inside the `layout` block. Wherever you measure, the rule is still once.\nMeasuring in the placement block means the child's size cannot affect the parent's size, because the parent has already reported its size [[src:ui-measure-once]] [[src:book-compose-ess]].")

    S = 'intrinsics'
    a(C + '.sec.%s.title' % S, 'Intrinsic: hỏi con trước khi đo', 'Intrinsics: asking children before measuring')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Đôi khi cha cần biết kích thước của con TRƯỚC khi chọn constraints, như ví dụ đường chia ở đầu chương. Đo thử thì bị cấm. Vì vậy Compose có intrinsic: hỏi con "bạn cần bao nhiêu chỗ?" trước khi đo thật (trang Intrinsic measurements).\nCó bốn modifier: `width(IntrinsicSize.Min)`, `width(IntrinsicSize.Max)`, `height(IntrinsicSize.Min)`, `height(IntrinsicSize.Max)` [[src:cp-intrinsics]].',
      'Sometimes a parent needs a child\'s size BEFORE choosing constraints, like the divider example at the top of the chapter. Trial measurement is forbidden. So Compose offers intrinsics: asking a child "how much room do you need?" before the real measurement (the Intrinsic measurements page).\nThere are four modifiers: `width(IntrinsicSize.Min)`, `width(IntrinsicSize.Max)`, `height(IntrinsicSize.Min)`, `height(IntrinsicSize.Max)` [[src:cp-intrinsics]].')
    B(C, S, 2, 'p', 'Min và Max nghĩa là gì? Lấy một `Text` làm ví dụ. Độ rộng Max của một dòng chữ bằng độ dài cả dòng, không xuống dòng. Độ rộng Min có thể hẹp tới đúng từ dài nhất, vì chữ có thể xuống nhiều dòng.\nKDoc ở commit ghim định nghĩa chính xác hơn: `minIntrinsicWidth(height)` là chiều rộng nhỏ nhất để nội dung vẽ đúng ở chiều cao đó; `maxIntrinsicWidth(height)` là chiều rộng nhỏ nhất mà tăng thêm cũng không làm min intrinsic height giảm nữa. Chiều cao cũng tương tự [[src:book-compose-ess]] [[src:ui-measurepolicy-src]].\nQuy tắc dễ nhớ: Min là "ép hết cỡ mà vẫn đúng"; Max là "thoải mái nhất, rộng thêm cũng vô ích".',
      'What do Min and Max mean? Take a `Text`. The Max width of a line of text is the full length of the line, with no wrapping. The Min width can be as narrow as the longest word, because the text can wrap onto several lines.\nThe KDoc at the pinned commit is more precise: `minIntrinsicWidth(height)` is the smallest width at which the content draws correctly at that height; `maxIntrinsicWidth(height)` is the smallest width beyond which widening no longer reduces the min intrinsic height. Heights work the same way [[src:book-compose-ess]] [[src:ui-measurepolicy-src]].\nRule of thumb: Min is "squeezed as far as it goes while still correct"; Max is "most comfortable, wider would not help".')
    B(C, S, 3, 'kt', '@Composable\nfun TwoTexts(text1: String, text2: String, modifier: Modifier = Modifier) {\n    Row(modifier = modifier.height(IntrinsicSize.Min)) {          // ✓\n        Text(text1, Modifier.weight(1f).padding(start = 4.dp).wrapContentWidth(Alignment.Start))\n        VerticalDivider(color = Color.Black, modifier = Modifier.fillMaxHeight().width(1.dp))\n        Text(text2, Modifier.weight(1f).padding(end = 4.dp).wrapContentWidth(Alignment.End))\n    }\n}')
    B(C, S, 4, 'p', 'Giải thích của tài liệu: `minIntrinsicHeight` của Row là giá trị lớn nhất trong các con. Của đường chia là 0, vì nó không chiếm chỗ khi không có constraints. Của Text là chiều cao của nó ở chiều rộng cho trước. Vậy constraints chiều cao của Row thành chiều cao của Text cao nhất, và đường chia giãn ra tới đó.\nĐiều quan trọng: hỏi intrinsic KHÔNG đo con hai lần. Con được hỏi trước, rồi mới được đo đúng một lần với constraints đã tính [[src:cp-intrinsics]].',
      "The docs' explanation: the Row's `minIntrinsicHeight` is the largest among its children. The divider's is 0, because it takes no space without constraints. A Text's is its height at the given width. So the Row's height constraint becomes the height of the tallest Text, and the divider stretches to it.\nThe important point: asking for intrinsics does NOT measure the children twice. The children are asked first, then measured exactly once with the computed constraints [[src:cp-intrinsics]].")
    B(C, S, 5, 'p', 'Layout tuỳ chỉnh thì sao? `MeasurePolicy` có bốn hàm intrinsic với cài đặt mặc định. Ở commit ghim, chúng bọc mỗi con trong một `DefaultIntrinsicMeasurable`, rồi chạy chính hàm `measure` của bạn với constraints chỉ có chiều còn lại (ví dụ `Constraints(maxHeight = height)`). KDoc gọi đó là xấp xỉ "cố hết sức", không đúng cho mọi layout.\nKhi cần, override hàm tương ứng và giữ nó khớp với `measure`. Ví dụ của tài liệu cho một cột tự viết: `minIntrinsicHeight` bằng tổng `minIntrinsicHeight(width)` của các con [[src:ui-measurepolicy-src]] [[src:cp-intrinsics]] [[src:book-kunneth]].',
      'What about custom layouts? `MeasurePolicy` has four intrinsic functions with default implementations. At the pinned commit, they wrap each child in a `DefaultIntrinsicMeasurable`, then run your own `measure` with constraints on the other axis only (for example `Constraints(maxHeight = height)`). The KDoc calls this a "best effort" approximation, not correct for every layout.\nWhen needed, override the matching function and keep it consistent with `measure`. The docs\' example for a hand-written column: `minIntrinsicHeight` equals the sum of the children\'s `minIntrinsicHeight(width)` [[src:ui-measurepolicy-src]] [[src:cp-intrinsics]] [[src:book-kunneth]].')
    B(C, S, 6, 'kt', 'object MyColumnPolicy : MeasurePolicy {\n    override fun MeasureScope.measure(measurables: List<Measurable>, constraints: Constraints): MeasureResult {\n        val placeables = measurables.map { it.measure(constraints.copy(minHeight = 0)) }\n        val width = constraints.constrainWidth(placeables.maxOfOrNull { it.width } ?: 0)\n        val height = constraints.constrainHeight(placeables.sumOf { it.height })\n        return layout(width, height) {\n            var y = 0\n            placeables.forEach { it.placeRelative(0, y); y += it.height }\n        }\n    }\n    // khớp với measure: chiều cao là tổng chiều cao con\n    override fun IntrinsicMeasureScope.minIntrinsicHeight(measurables: List<IntrinsicMeasurable>, width: Int): Int =\n        measurables.sumOf { it.minIntrinsicHeight(width) }\n}', 'object MyColumnPolicy : MeasurePolicy {\n    override fun MeasureScope.measure(measurables: List<Measurable>, constraints: Constraints): MeasureResult {\n        val placeables = measurables.map { it.measure(constraints.copy(minHeight = 0)) }\n        val width = constraints.constrainWidth(placeables.maxOfOrNull { it.width } ?: 0)\n        val height = constraints.constrainHeight(placeables.sumOf { it.height })\n        return layout(width, height) {\n            var y = 0\n            placeables.forEach { it.placeRelative(0, y); y += it.height }\n        }\n    }\n    // consistent with measure: the height is the sum of the children\'s heights\n    override fun IntrinsicMeasureScope.minIntrinsicHeight(measurables: List<IntrinsicMeasurable>, width: Int): Int =\n        measurables.sumOf { it.minIntrinsicHeight(width) }\n}')
    B(C, S, 7, 'note', 'Intrinsic không miễn phí: câu hỏi đi đệ quy xuống cả cây con. Tài liệu không đưa số đo chi phí; KDoc chỉ nói đa số layout không cần hỏi intrinsic. Nên chỉ dùng khi luật "đo một lần" thật sự cản bạn [[src:ui-measurepolicy-src]].',
      'Intrinsics are not free: the question recurses down the whole subtree. The docs give no cost figures; the KDoc only says most layouts do not need intrinsic queries. So use them only when the "measure once" rule really gets in your way [[src:ui-measurepolicy-src]].')
    B(C, S, 7, 'kind', 'pitfall')

    S = 'subcompose'
    a(C + '.sec.%s.title' % S, 'SubcomposeLayout: compose trong lúc đo', 'SubcomposeLayout: composing during measurement')
    a(C + '.sec.%s.badge' % S, 'impl')
    B(C, S, 1, 'p', 'B7 nói thứ tự phase là một chiều, trừ vài ngoại lệ như `BoxWithConstraints`, `LazyColumn`, `LazyRow`. Ngoại lệ đó tên là `SubcomposeLayout`: một "bản tương tự của Layout" cho phép compose nội dung con NGAY trong bước đo. Nhờ vậy, giá trị tính được lúc đo dùng được làm tham số cho composition của con.\nTrong khối đo, `subcompose(slotId) { … }` compose một slot và trả về danh sách `Measurable` để đo tiếp [[src:ui-subcompose-src]] [[src:cp-phases]].\nQuy tắc dễ nhớ: cần biết "còn bao nhiêu chỗ" rồi mới quyết "vẽ gì" thì đó là việc của `SubcomposeLayout`.',
      'B7 said the phase order is one-way, except for a few cases like `BoxWithConstraints`, `LazyColumn` and `LazyRow`. That exception is called `SubcomposeLayout`: an "analogue of Layout" that lets you compose children\'s content RIGHT in the measure step. So values computed while measuring can be used as parameters for the children\'s composition.\nInside the measure block, `subcompose(slotId) { … }` composes one slot and returns a list of `Measurable`s to measure next [[src:ui-subcompose-src]] [[src:cp-phases]].\nRule of thumb: when you must know "how much room is left" before deciding "what to draw", that is a job for `SubcomposeLayout`.')
    B(C, S, 2, 'p', 'KDoc ở commit ghim liệt kê ba trường hợp dùng:\n1. Cần biết constraints của cha trong lúc composition, mà không giải được bằng `Layout` hay layout modifier. Ví dụ `BoxWithConstraints`.\n2. Cần kích thước của một con khi compose con kia.\n3. Compose lười theo chỗ trống: danh sách 100 mục mà chỉ compose khoảng 5 mục đang thấy, và compose thêm khi cuộn. Trường hợp này là nền móng của lazy list (LZ).\n`slotId` phải bằng nhau (`equals`) giữa các lần đo để nội dung khớp lại đúng, giống vai trò của key ở B3 [[src:ui-subcompose-src]].',
      "The KDoc at the pinned commit lists three use cases:\n1. You need the parent's constraints during composition, and cannot solve it with `Layout` or a layout modifier. For example `BoxWithConstraints`.\n2. You need one child's size while composing another.\n3. Lazy composing by available space: a list of 100 items where only the roughly 5 visible items are composed, and more are composed as you scroll. This case is the foundation of lazy lists (LZ).\nThe `slotId` must be equal (`equals`) across measurements so content is matched up correctly, like the role of keys in B3 [[src:ui-subcompose-src]].")
    B(C, S, 3, 'kt', '@Composable\nfun WithConstraintsComposable() {\n    BoxWithConstraints {\n        // minHeight, maxWidth… có ngay trong scope của content\n        if (maxWidth < 600.dp) CompactLayout() else WideLayout()\n    }\n}', '@Composable\nfun WithConstraintsComposable() {\n    BoxWithConstraints {\n        // minHeight, maxWidth… are available right in the content scope\n        if (maxWidth < 600.dp) CompactLayout() else WideLayout()\n    }\n}')
    B(C, S, 4, 'p', 'Trang Layout basics dùng `BoxWithConstraints` để compose bố cục khác nhau cho những cỡ màn hình khác nhau. Cái giá: composition bị dời vào phase layout. Vì vậy chỉ dùng nó khi nội dung THẬT SỰ phụ thuộc vào constraints.\nNếu chỉ cần đặt hay co giãn con theo chỗ trống, một `Layout` hoặc một modifier thường là đủ, như chính KDoc gợi ý [[src:cp-layout-basics]] [[src:ui-subcompose-src]].',
      'The Layout basics page uses `BoxWithConstraints` to compose different layouts for different screen sizes. The price: composition is moved into the layout phase. So use it only when the content REALLY depends on the constraints.\nIf you only need to place or resize children by the available space, a `Layout` or a modifier is usually enough, as the KDoc itself suggests [[src:cp-layout-basics]] [[src:ui-subcompose-src]].')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Một layout tùy chỉnh crash ngay khi hiện: `IllegalStateException: measure() may not be called multiple times on the same Measurable…`.', 'A custom layout crashes as soon as it appears: `IllegalStateException: measure() may not be called multiple times on the same Measurable…`.')
    B(C, S, 1, 'cause', 'Mã đo con một lần để lấy chiều rộng, rồi đo lại với constraints mới (như kịch bản "đo hai lần" của mô phỏng). Compose cho phép đúng một lần đo mỗi lượt.', 'The code measures a child once to read its width, then again with new constraints (like the simulation\'s "measure twice" scenario). Compose allows exactly one measurement per pass.')
    B(C, S, 1, 'fix', 'Hỏi `measurable.maxIntrinsicWidth(constraints.maxHeight)` (hoặc hàm intrinsic phù hợp) trước, tính constraints cuối từ đó, rồi đo một lần.', 'Ask `measurable.maxIntrinsicWidth(constraints.maxHeight)` (or the matching intrinsic function) first, compute the final constraints from it, then measure once.')
    B(C, S, 1, 'fixkt', 'Layout(content = content) { measurables, constraints ->\n    val m = measurables[0]\n    val natural = m.maxIntrinsicWidth(constraints.maxHeight)          // câu hỏi, chưa đo\n    val p = m.measure(constraints.copy(maxWidth = natural / 2))       // đo đúng một lần\n    layout(p.width, p.height) { p.placeRelative(0, 0) }\n}', 'Layout(content = content) { measurables, constraints ->\n    val m = measurables[0]\n    val natural = m.maxIntrinsicWidth(constraints.maxHeight)          // a query, not a measurement\n    val p = m.measure(constraints.copy(maxWidth = natural / 2))       // measured exactly once\n    layout(p.width, p.height) { p.placeRelative(0, 0) }\n}')
    B(C, S, 2, 'bug', 'Đường chia dọc giữa hai cột chữ kéo dài xuống tận đáy màn hình.', 'A vertical divider between two text columns stretches all the way to the bottom of the screen.')
    B(C, S, 2, 'cause', '`fillMaxHeight()` trong một `Row` không có chiều cao: con nhận chiều cao tối đa của cha, và Row lấy chiều cao của con cao nhất, chính là đường chia.', '`fillMaxHeight()` inside a `Row` without a height: the child gets the parent\'s maximum height, and the Row takes the height of its tallest child, which is the divider.')
    B(C, S, 2, 'fix', 'Thêm `Modifier.height(IntrinsicSize.Min)` cho Row. [[src:cp-intrinsics]]', 'Add `Modifier.height(IntrinsicSize.Min)` to the Row. [[src:cp-intrinsics]]')
    B(C, S, 3, 'bug', 'Đặt cột tự viết (`MyColumnPolicy` nhưng chưa override intrinsic) vào `Row(Modifier.height(IntrinsicSize.Min))` cạnh một `Text`: Row có chiều cao sai so với tổng chiều cao các mục trong cột.', 'Put a hand-written column (`MyColumnPolicy` without the intrinsic override) into a `Row(Modifier.height(IntrinsicSize.Min))` next to a `Text`: the Row\'s height does not match the column\'s total item height.')
    B(C, S, 3, 'cause', 'Không override thì intrinsic dùng cài đặt mặc định, chạy `measure` của bạn trên các measurable bọc làm xấp xỉ. KDoc nói xấp xỉ này không đúng với mọi layout.', 'Without an override, intrinsics use the default implementation, which approximates by running your `measure` over wrapped measurables. The KDoc says this approximation is not correct for every layout.')
    B(C, S, 3, 'fix', 'Override `minIntrinsicHeight` (và các hàm khác nếu được hỏi) cho khớp `measure`: tổng `minIntrinsicHeight(width)` của các con. [[src:cp-intrinsics]] [[src:ui-measurepolicy-src]]', 'Override `minIntrinsicHeight` (and the others if they are queried) to match `measure`: the sum of the children\'s `minIntrinsicHeight(width)`. [[src:cp-intrinsics]] [[src:ui-measurepolicy-src]]')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Gọi `CascadeLayout(spacing = 20)` với năm `Box`: 60×60, 80×40, 90×100, 50×50, 70×70. Mỗi con được đặt ở (indent, yCoord), sau đó `indent += width + spacing` và `yCoord += height + spacing`. Giả sử mọi số cùng đơn vị (đừng trộn `spacing` kiểu Int với kích thước dp; ở đây coi như cùng đơn vị). Tính vị trí năm con.', 'Call `CascadeLayout(spacing = 20)` with five `Box`es: 60×60, 80×40, 90×100, 50×50, 70×70. Each child is placed at (indent, yCoord), then `indent += width + spacing` and `yCoord += height + spacing`. Assume all numbers are in the same unit (do not mix an Int `spacing` with dp sizes; treat them as one unit here). Compute the five positions.')
    B(C, S, 1, 'hint', 'Con đầu ở (0, 0). Sau con đầu: indent = 0 + 60 + 20.', 'The first child is at (0, 0). After it: indent = 0 + 60 + 20.')
    B(C, S, 1, 'sol', '(0, 0), (80, 80), (180, 140), (290, 260), (360, 330). Ví dụ: con 3 ở indent = 80 + 80 + 20 = 180, y = 80 + 40 + 20 = 140.', '(0, 0), (80, 80), (180, 140), (290, 260), (360, 330). For example, child 3 is at indent = 80 + 80 + 20 = 180, y = 80 + 40 + 20 = 140.')
    B(C, S, 2, 'ex', 'Viết `MyRow`: đo mỗi con với `minWidth = 0`, xếp từ trái sang phải, chiều rộng bằng tổng (bị ép trong constraints) và chiều cao bằng con cao nhất.', 'Write `MyRow`: measure each child with `minWidth = 0`, lay them out left to right, with a width equal to the sum (coerced into the constraints) and a height equal to the tallest child.')
    B(C, S, 2, 'hint', 'Dùng `constraints.copy(minWidth = 0)`, `constrainWidth`, `constrainHeight`, và một biến `x` tích lũy trong khối đặt.', 'Use `constraints.copy(minWidth = 0)`, `constrainWidth`, `constrainHeight`, and an accumulating `x` in the placement block.')
    B(C, S, 2, 'solkt', '@Composable\nfun MyRow(modifier: Modifier = Modifier, content: @Composable () -> Unit) {\n    Layout(modifier = modifier, content = content) { measurables, constraints ->\n        val placeables = measurables.map { it.measure(constraints.copy(minWidth = 0)) }\n        val width = constraints.constrainWidth(placeables.sumOf { it.width })\n        val height = constraints.constrainHeight(placeables.maxOfOrNull { it.height } ?: 0)\n        layout(width, height) {\n            var x = 0\n            placeables.forEach { it.placeRelative(x, 0); x += it.width }\n        }\n    }\n}')
    B(C, S, 2, 'sol', 'Mỗi con được đo đúng một lần. `placeRelative` tự lật thứ tự khi RTL.', 'Each child is measured exactly once. `placeRelative` mirrors the order automatically in RTL.')
    B(C, S, 3, 'ex', 'Bạn muốn một `Column` có chiều rộng bằng nút RỘNG NHẤT trong nó, và mọi nút giãn bằng nhau (`fillMaxWidth()`). Không đặt chiều rộng cố định. Viết bằng modifier có sẵn.', 'You want a `Column` as wide as the WIDEST button in it, with every button stretched equally (`fillMaxWidth()`). No fixed width. Write it with built-in modifiers.')
    B(C, S, 3, 'hint', 'Giống ví dụ đường chia nhưng theo chiều rộng: hỏi intrinsic của Column theo chiều ngang.', 'Like the divider example but horizontally: ask for the Column\'s intrinsic width.')
    B(C, S, 3, 'solkt', 'Column(Modifier.width(IntrinsicSize.Max)) {\n    Button(onClick = {}, Modifier.fillMaxWidth()) { Text("OK") }\n    Button(onClick = {}, Modifier.fillMaxWidth()) { Text("Cancel and go back") }\n}')
    B(C, S, 3, 'sol', '`IntrinsicSize.Max`: chiều rộng đủ cho nội dung rộng nhất không xuống dòng; rồi `fillMaxWidth()` của từng nút lấp đúng chiều rộng đó. Đặt `width(IntrinsicSize.Max)` cho Column cũng theo cùng ý. `Min` sẽ cho chiều rộng theo từ dài nhất, làm chữ nút xuống dòng.', '`IntrinsicSize.Max`: wide enough for the widest content without wrapping; then each button\'s `fillMaxWidth()` fills exactly that width. Putting `width(IntrinsicSize.Max)` on a Column follows the same idea. `Min` would give the width of the longest word, making the button labels wrap.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Ba bước mỗi node làm trong layout?', 'The three steps each node does in layout?')
    B(C, S, 1, 'ans', 'Đo các con, quyết kích thước của mình, đặt các con.', 'Measure its children, decide its own size, place its children.')
    B(C, S, 2, 'ask', 'Vì sao Compose cấm đo một con hai lần?', 'Why does Compose forbid measuring a child twice?')
    B(C, S, 2, 'ans', 'Để layout là một lượt, tuyến tính theo số node; đo lặp ở mỗi tầng sẽ nhân số lần đo theo độ sâu của cây.', 'So layout is a single pass, linear in the number of nodes; repeated measurement at each level would multiply the work by the depth of the tree.')
    B(C, S, 3, 'ask', 'Hỏi intrinsic có phải là đo lần hai không?', 'Is asking for intrinsics a second measurement?')
    B(C, S, 3, 'ans', 'Không. Con được hỏi trước khi đo; cha tính constraints từ câu trả lời rồi đo một lần.', 'No. Children are queried before measurement; the parent computes constraints from the answers, then measures once.')
    B(C, S, 4, 'ask', 'Khi nào cần `SubcomposeLayout`/`BoxWithConstraints` thay vì `Layout`?', 'When do you need `SubcomposeLayout`/`BoxWithConstraints` instead of `Layout`?')
    B(C, S, 4, 'ans', 'Khi chính NỘI DUNG cần compose (không chỉ đặt) phụ thuộc constraints hay kích thước con khác, hoặc khi compose lười theo chỗ trống.', 'When the CONTENT to compose (not just its placement) depends on the constraints or another child\'s size, or when composing lazily by available space.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Trong khung 300×200, `Modifier.fillMaxSize().size(50.dp)` cho kích thước nào?', 'In a 300×200 container, what size does `Modifier.fillMaxSize().size(50.dp)` give?',
         '300×200.', '300×200.', '`fillMaxSize` tạo constraints exact; `size` phải tôn trọng chúng.', '`fillMaxSize` creates exact constraints; `size` must respect them.'),
        ('q2', '`placeRelative` khác `place` ở điểm nào?', 'How does `placeRelative` differ from `place`?',
         'Lật trục x khi RTL.', 'It mirrors x in RTL.', '`place` giữ nguyên tọa độ bất kể hướng bố cục.', '`place` keeps the coordinates whatever the layout direction.'),
        ('q3', '`minIntrinsicHeight` của một `Row` được tính thế nào trong ví dụ TwoTexts?', 'How is a `Row`\'s `minIntrinsicHeight` computed in the TwoTexts example?',
         'Giá trị lớn nhất của các con.', 'The largest of its children\'s.', 'Đường chia góp 0, mỗi Text góp chiều cao ở chiều rộng của nó.', 'The divider contributes 0, each Text its height at its width.'),
        ('q4', 'Layout tùy chỉnh không override intrinsic thì sao?', 'What happens if a custom layout does not override intrinsics?',
         'Dùng xấp xỉ mặc định dựa trên `measure`.', 'A default approximation based on `measure` is used.', 'KDoc: tiện, nhưng không đúng với mọi layout.', 'KDoc: convenient, but not correct for every layout.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
